<style>
.pw-shell{max-width:1200px;margin:auto;color:var(--text-primary);display:grid;gap:1rem}.pw-head,.pw-card{border:1px solid var(--border);background:var(--surface-3);border-radius:1rem;padding:1.25rem}.pw-head h1{font-size:1.5rem;font-weight:700}.pw-kicker{font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--brand)}.pw-muted{font-size:.85rem;color:var(--text-secondary)}.pw-row{display:flex;align-items:center;justify-content:space-between;gap:.75rem;flex-wrap:wrap}.pw-actions{display:flex;gap:.5rem;flex-wrap:wrap;align-items:center}.pw-btn{display:inline-flex;align-items:center;justify-content:center;gap:.4rem;min-height:42px;padding:.6rem 1rem;border:1px solid var(--border);border-radius:.6rem;font-size:.85rem;font-weight:600;background:var(--surface-1);color:var(--text-primary);text-decoration:none}.pw-primary{background:var(--brand);border-color:var(--brand);color:white}.pw-btn:disabled{opacity:.5;cursor:not-allowed}.pw-btn:focus-visible,.pw-input:focus-visible{outline:3px solid var(--brand);outline-offset:2px}.pw-badge{border-radius:99px;padding:.25rem .65rem;font-size:.72rem;font-weight:600;background:var(--surface-2);color:var(--text-secondary)}.pw-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:1rem}.pw-field{display:grid;gap:.35rem;align-content:start;font-size:.85rem;font-weight:600}.pw-input{width:100%;min-width:0;border:1px solid var(--border);border-radius:.55rem;min-height:44px;background:var(--surface-1);color:var(--text-primary);padding:.65rem .75rem;font-weight:400}.pw-table-wrap{overflow-x:auto}.pw-table{width:100%;border-collapse:collapse;font-size:.85rem}.pw-table th,.pw-table td{text-align:left;padding:.8rem;border-bottom:1px solid var(--border);vertical-align:top}.pw-table th{font-size:.72rem;text-transform:uppercase;color:var(--text-secondary)}.pw-stack{display:grid;gap:1rem}.pw-order{padding:.8rem 1rem;border:1px solid var(--border);border-radius:.7rem;background:var(--surface-2)}.pw-flow-cue{display:grid;gap:.25rem;padding:.85rem 1rem;border:1px solid var(--border);border-left:4px solid var(--brand);border-radius:.7rem;background:var(--surface-1);font-size:.85rem}.pw-flow-cue strong{font-size:.72rem;text-transform:uppercase;letter-spacing:.05em;color:var(--brand)}.pw-notice{padding:.9rem 1rem;border:1px solid var(--status-good);border-radius:.7rem;background:var(--status-good-bg);color:var(--status-good);font-size:.85rem}.pw-error{padding:.9rem 1rem;border:1px solid var(--status-critical);border-radius:.7rem;background:var(--status-critical-bg);color:var(--status-critical);font-size:.85rem}.pw-field-error{font-size:.78rem;color:var(--status-critical)}.pw-history{border-left:3px solid var(--brand);padding-left:1rem}.pw-shell h2{font-size:1.05rem;font-weight:700}.pw-shell summary{cursor:pointer;font-weight:600}.pw-shell [x-cloak]{display:none!important}.pw-empty{text-align:center;padding:2.5rem 1rem;color:var(--text-secondary)}@media(max-width:640px){.pw-head,.pw-card{padding:1rem}.pw-head h1{font-size:1.3rem}.pw-actions .pw-btn{flex:1}.pw-order{font-size:.85rem}.pw-table th,.pw-table td{padding:.65rem}.pw-row{align-items:flex-start}}
.pw-shell,.pw-card,.pw-stack,.pw-order{min-width:0}.pw-field{min-width:0;max-width:100%}.pw-input{max-width:100%;box-sizing:border-box}.pw-table .pw-input{min-width:90px}
</style>
